import React from 'react'
import { useState } from 'react';
import axios from 'axios';

function Login() {
  return (
    <div>
      <h1>Login</h1>
      <form onSubmit={(e) => onSubmit(e)}>

        <label htmlFor="email">email</label><br />
        <input type="email" id="email" name="email" value={email} onChange={(e) => onInputChange(e)} required /><br />

        <label htmlFor="password">password</label><br />
        <input type="password" id="password" name="password" value={password} onChange={(e) => onInputChange(e)} required /><br />

        <button type="submit" className="fom_btn">login</button>
      </form>
    </div>
  )
}

export default Login
